"""Konvertiert CSV-Dateien in eine einheitliche Zeichenkodierung."""

import codecs
from pathlib import Path

from charset_normalizer import from_bytes


def csv_zu_utf8_bom(eingabe_datei: str | Path, ausgabe_datei: str | Path) -> str:
    """Konvertiert eine CSV-Datei nach UTF-8 mit BOM.

    Args:
        eingabe_datei: Pfad der Quelldatei.
        ausgabe_datei: Pfad der zu erzeugenden UTF-8-BOM-Datei.

    Returns:
        Die erkannte Zeichenkodierung der Quelldatei.
    """
    eingabe_pfad = Path(eingabe_datei)
    ausgabe_pfad = Path(ausgabe_datei)

    daten = eingabe_pfad.read_bytes()

    # Vorhandene Byte Order Marks erkennen
    if daten.startswith((codecs.BOM_UTF32_LE, codecs.BOM_UTF32_BE)):
        quell_encoding = "utf-32"
    elif daten.startswith((codecs.BOM_UTF16_LE, codecs.BOM_UTF16_BE)):
        quell_encoding = "utf-16"
    elif daten.startswith(codecs.BOM_UTF8):
        quell_encoding = "utf-8-sig"
    else:
        try:
            daten.decode("utf-8")
            quell_encoding = "utf-8"
        except UnicodeDecodeError:
            ergebnis = from_bytes(daten).best()

            if ergebnis is None:
                raise ValueError("Die Codierung konnte nicht erkannt werden.") from None

            quell_encoding = ergebnis.encoding

    text = daten.decode(quell_encoding)

    # Ausgabeordner bei Bedarf erstellen
    ausgabe_pfad.parent.mkdir(parents=True, exist_ok=True)

    ausgabe_pfad.write_text(text, encoding="utf-8-sig", newline="")

    return quell_encoding
